final_call.output:
```javascript
function uniqueSorted(numbers) {
  return [...new Set(numbers)].sort((a, b) => a - b);
}

console.log(uniqueSorted([3, 1, 2, 3, 1]));  // [1, 2, 3]
console.log(uniqueSorted([0, -2, 4, -2, 0])); // [-2, 0, 4]
console.log(uniqueSorted([]));                 // []
```

